"use strict";(globalThis.webpackChunkgrc||=[]).push([[98569],{26322(e){e.exports=JSON.parse('{"citeKey":"chen2010adaptivedata","slug":"chen-2010-adaptive-data-404a","title":"An Adaptive Data Prefetcher for High-Performance Processors","authors":["Y. Chen","H. Zhu","X.-H. Sun"],"venue":"The 10th IEEE/ACM International Symposium on Cluster, Cloud and Grid Computing (CCGrid\'10), Melbourne, Australia","type":"Conference","entryType":"inproceedings","date":"May, 2010","year":2010,"era":"iit","month":5,"doi":"10.1109/ccgrid.2010.61","abstract":"While computing speed continues increasing rapidly, data-access technology is lagging behind. Data-access delay, not the processor speed, becomes the leading performance bottleneck of high-end/high-performance computing. Prefetching is an effective solution to masking the gap between computing speed and data-access speed. Existing works of prefetching, however, are very conservative in general, due to the computing power consumption concern of the past. They suffer in effectiveness especially when applications\' access pattern changes. In this study, we propose an Algorithm-level Feedback-controlled Adaptive (AFA) data prefetcher to address these issues. The AFA prefetcher is based on the Data-Access History Cache, a hardware structure that is specifically designed for data prefetching. It provides an algorithm-level adaptation and is capable of dynamically adapting to appropriate prefetching algorithms at runtime. We have conducted extensive simulation testing with SimpleScalar simulator to validate the design and to illustrate the performance gain. The simulation results show that AFA prefetcher is effective and achieves considerable IPC (Instructions Per Cycle) improvement in average.","hasAbstract":true,"lede":"While computing speed continues increasing rapidly, data-access technology is lagging behind.","links":{"pdf":"https://grc.iit.edu/papers/2010/chen-2010-adaptive-data-404a.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":[],"memberAuthors":["sun-xian-he"]}')}}]);